-- 430: WASSCE English letter and report writing multiple-choice set B (batch sprint 1).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_430_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_430_guard;
INSERT INTO _migration_430_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_005' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a formal letter, the heading is normally written' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. in capital letters, and it may be underlined","B. in small letters only","C. in red ink without exception","D. after the subscription at the end"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The heading announces the subject and is conventionally written in capital letters, sometimes underlined, and placed after the salutation.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_005' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_430_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_006' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The subscription "Yours faithfully" is correctly paired with the salutation' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Dear Mr Mensah,","B. Dear Sir,","C. Dear Akosua,","D. My dear Father,"]' AND q.correct_answer IS 'B' AND q.explanation IS 'An unnamed recipient ("Dear Sir") takes "Yours faithfully"; a named recipient ("Dear Mr Mensah") takes "Yours sincerely".' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Choose' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_006' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_430_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_007' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which list gives the correct order of the opening parts of a formal letter?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Date, salutation, writer''s address, recipient''s address","B. Recipient''s address, writer''s address, salutation, date","C. Writer''s address, date, recipient''s address, salutation","D. Salutation, writer''s address, date, recipient''s address"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The conventional layout is writer''s address, date, recipient''s address on the left, then the salutation; every other sequence misplaces a part.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Order' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_007' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_430_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_008' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A letter to the editor of a newspaper differs from a letter to a friend chiefly because it' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. is always written entirely in capital letters","B. needs no address or date at all","C. must be written by a professional journalist","D. uses a formal register and the full formal-letter format for a public audience"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A letter to the editor is a formal public document, so it keeps the full formal format and a restrained register even when the subject is a personal grievance.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_008' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_430_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_009' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In an official report, the section headed "terms of reference" states' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. what the writer was instructed to investigate and report on","B. the names of all the members of the committee","C. the recommendations of the report","D. the cost of writing the report"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The terms of reference record the mandate: who asked for the report and exactly what it was to cover.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_009' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
